    z_t58_t* boxed = (z_t58_t*)z_xmalloc(sizeof(z_t58_t));
    boxed->data = self->data + p->size;
    boxed->size = self->size - p->size;
    out.tag = Z_T13626_TAG_1;
    out.data = boxed;
