static const z_t5814_t _zag2913 = { { .data = "sqlite_utf8", .size = 11 }, { .length = 1, .data = _zag2912 }, { .length = 0, .data = NULL }, { .data = "/* whether `n` bytes at `p` are well-formed UTF-8 (no overlongs, surrogates\n   or code points past U+10FFFF) */\nstatic bool z_sqlite_utf8(const unsigned char* p, uint64_t n) {\n    uint64_t i = 0;\n    while (i < n) {\n        unsigned char c = p[i];\n        if (c < 0x80) { i++; continue; }\n        uint64_t len; uint32_t cp;\n        if ((c & 0xE0) == 0xC0) { len = 2; cp = c & 0x1F; }\n        else if ((c & 0xF0) == 0xE0) { len = 3; cp = c & 0x0F; }\n        else if ((c & 0xF8) == 0xF0) { len = 4; cp = c & 0x07; }\n        else return false;\n        if (i + len > n) return false;\n        for (uint64_t k = 1; k < len; k++) {\n            if ((p[i + k] & 0xC0) != 0x80) return false;\n            cp = (cp << 6) | (p[i + k] & 0x3F);\n        }\n        if ((len == 2 && cp < 0x80) || (len == 3 && cp < 0x800) || (len == 4 && cp < 0x10000)) return false;\n        if (cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) return false;\n        i += len;\n    }\n    return true;\n}", .size = 966 } };
